<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/services.php';
$db=db();
if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';if(!$name||!$email||strlen($password)<8)throw new RuntimeException('Add a store name, valid email, and password of at least 8 characters.');$slug=slug($name);$check=$db->prepare('SELECT id FROM tenants WHERE slug=?');$check->execute([$slug]);if($check->fetch())$slug.='-'.bin2hex(random_bytes(2));$db->beginTransaction();$s=$db->prepare('INSERT INTO tenants (slug,name,tagline,description) VALUES (?,?,?,?)');$s->execute([$slug,$name,trim($_POST['tagline']??''),trim($_POST['description']??'')]);$tenantId=(int)$db->lastInsertId();$u=$db->prepare('INSERT INTO users (tenant_id,role,name,email,password_hash) VALUES (?,?,?,?,?)');$u->execute([$tenantId,'admin',trim($_POST['owner_name']??'Store owner'),$email,password_hash($password,PASSWORD_DEFAULT)]);$db->commit();$_SESSION['user_id']=$db->lastInsertId();flash('Your store is ready for setup.');redirect('/admin/?store='.$slug);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash($e->getMessage(),'error');redirect('/setup');}
